use vstd::prelude::*;

/// Given:
/// - `src`: source array of i32
/// - `s_start`: start index in source for copying
/// - `dest`: destination array of i32
/// - `d_start`: start index in destination to overwrite
/// - `len`: number of elements to copy
///
/// Returns a new vector of same length as `dest`
/// which is identical to `dest` except the segment
/// `[d_start..d_start+len)` is replaced with the
/// slice `[s_start..s_start+len)` from `src`.
/// 
/// Requirements:
/// - `s_start + len <= src.len()`
/// - `d_start + len <= dest.len()`
